import{_ as t,o as h,c as i,a3 as g}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Có gì mới","description":"","frontmatter":{},"headers":[],"relativePath":"cap-nhat.md","filePath":"cap-nhat.md","lastUpdated":1783009205000}'),a={name:"cap-nhat.md"};function o(c,n,r,e,l,s){return h(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="co-gi-moi" tabindex="-1">Có gì mới <a class="header-anchor" href="#co-gi-moi" aria-label="Permalink to &quot;Có gì mới&quot;">​</a></h1><p>Nhật ký cập nhật tính năng của FADO AssetFlow. Trang này liệt kê các thay đổi nổi bật dành cho người dùng.</p><div class="tip custom-block"><p class="custom-block-title">Theo dõi cập nhật</p><p>Mỗi đợt nâng cấp đáng chú ý sẽ được ghi tại đây. Nếu thấy giao diện thay đổi, hãy ghé trang này để biết &quot;có gì mới&quot;.</p></div><h2 id="thang-7-2026" tabindex="-1">Tháng 7 / 2026 <a class="header-anchor" href="#thang-7-2026" aria-label="Permalink to &quot;Tháng 7 / 2026&quot;">​</a></h2><h3 id="⏱️-cham-cong-bang-cong" tabindex="-1">⏱️ Chấm công &amp; Bảng công <a class="header-anchor" href="#⏱️-cham-cong-bang-cong" aria-label="Permalink to &quot;⏱️ Chấm công &amp; Bảng công&quot;">​</a></h3><ul><li><strong>Bảng công tự gửi — bỏ nộp/duyệt thủ công.</strong> Nhân viên chỉ cần chấm công đầy đủ; hệ thống <strong>tự chốt &amp; gửi</strong> bảng công về Bộ Phận Chấm Công khi tới hạn. Bỏ nút <em>Nộp Bảng Công</em> và trang <em>Xác Nhận Bảng Công</em>.</li><li><strong>Phân hệ &quot;Bảng Công&quot; mới (chỉ xem)</strong> trong Dữ Liệu Chấm Công — nhóm theo <strong>Công Ty → Phòng Ban</strong>, xem chi tiết chấm công theo ngày, có <strong>tìm kiếm theo tên + lọc</strong> Công ty/Phòng ban/Trạng thái. Người dùng thấy mình · Quản lý thấy cấp dưới · Admin thấy công ty · Super Admin thấy toàn hệ thống.</li><li><strong>🆕 Hồ Sơ Chuyên Cần</strong> — tổng hợp đúng giờ / đi trễ / về sớm / vắng / nghỉ phép và <strong>điểm &amp; xếp loại</strong> chuyên cần từng nhân sự, có chi tiết theo ngày. Lọc theo Tháng/Quý/Năm/Tùy chỉnh.</li></ul><h3 id="🛠️-quy-tac-cham-cong-super-admin" tabindex="-1">🛠️ Quy Tắc Chấm Công (Super Admin) <a class="header-anchor" href="#🛠️-quy-tac-cham-cong-super-admin" aria-label="Permalink to &quot;🛠️ Quy Tắc Chấm Công (Super Admin)&quot;">​</a></h3><ul><li><strong>🆕 Giờ làm theo từng thứ trong tuần</strong> — đặt giờ vào–ra riêng cho mỗi thứ (T7 nửa buổi, CN nghỉ…) thay cho việc chỉ đánh dấu ngày nghỉ. Đi trễ / về sớm tính đúng theo ca thực từng ngày.</li><li><strong>🆕 Khung Buổi Sáng / Buổi Chiều</strong> — cấu hình được; hỗ trợ nghỉ phép nửa buổi.</li><li><strong>🆕 Thời gian tự gửi Bảng Công</strong> + tùy chọn <strong>&quot;Mốc rơi vào tháng kế tiếp của kỳ&quot;</strong> (cho công ty tính kỳ theo tháng dương lịch, hạn là ngày đầu tháng sau).</li><li><strong>🆕 Sửa phiên bản cấu hình đã lưu</strong> — nạp lại vào form và lưu đè.</li></ul><h3 id="🏖️-nghi-phep" tabindex="-1">🏖️ Nghỉ phép <a class="header-anchor" href="#🏖️-nghi-phep" aria-label="Permalink to &quot;🏖️ Nghỉ phép&quot;">​</a></h3><ul><li><strong>🆕 Nghỉ nửa buổi</strong> — nút chọn nhanh <em>Nghỉ buổi sáng / buổi chiều</em> tự điền khung giờ theo cấu hình công ty (0.5 ngày).</li></ul><h2 id="thang-6-2026" tabindex="-1">Tháng 6 / 2026 <a class="header-anchor" href="#thang-6-2026" aria-label="Permalink to &quot;Tháng 6 / 2026&quot;">​</a></h2><h3 id="📱-trai-nghiem-đien-thoai" tabindex="-1">📱 Trải nghiệm điện thoại <a class="header-anchor" href="#📱-trai-nghiem-đien-thoai" aria-label="Permalink to &quot;📱 Trải nghiệm điện thoại&quot;">​</a></h3><ul><li><strong>Giao diện điện thoại kiểu app</strong> — thanh tab dưới đáy (Trang chủ · Chấm công · Duyệt/Công việc · Menu · Tài khoản) thay cho sidebar; mọi chức năng khác gom trong tab <strong>Menu</strong> (vẫn lọc theo quyền).</li><li><strong>Cài đặt lên màn hình chính (PWA)</strong> — cài thẳng FADO AssetFlow lên điện thoại Android (Chrome) &amp; iPhone/iPad (Safari), mở toàn màn hình như ứng dụng thật, không cần App Store/CH Play. Xem <a href="/help/bat-dau/dien-thoai.html">Dùng trên điện thoại &amp; cài app</a>.</li></ul><h3 id="🆕-tai-san-tra-cuu" tabindex="-1">🆕 Tài sản &amp; Tra cứu <a class="header-anchor" href="#🆕-tai-san-tra-cuu" aria-label="Permalink to &quot;🆕 Tài sản &amp; Tra cứu&quot;">​</a></h3><ul><li><strong>Tra Cứu Tài Sản gộp 4 loại</strong> — Phần cứng, Tên miền, Email, Phần mềm hiển thị chung một nơi, có bộ lọc theo loại và thẻ tổng quan.</li><li><strong>Phân quyền xem tài sản theo vai trò:</strong> Người dùng thấy tài sản của mình · Quản lý thấy thêm cấp dưới · Admin thấy toàn công ty · Super Admin thấy toàn hệ thống.</li><li><strong>Chọn người phụ trách theo cơ cấu</strong> — khi thêm Tên miền / Email / Phần mềm, chọn người phụ trách theo cây Công ty → Phòng ban → Bộ phận (mỗi cấp có tìm kiếm).</li><li>Form <strong>Tên miền / Email / Phần mềm</strong> bổ sung nhiều trường (tài khoản, SSL, chi phí, ngày mua…).</li></ul><h3 id="🏢-to-chuc" tabindex="-1">🏢 Tổ chức <a class="header-anchor" href="#🏢-to-chuc" aria-label="Permalink to &quot;🏢 Tổ chức&quot;">​</a></h3><ul><li><strong>Logo công ty</strong> — tải logo cho từng công ty trong <em>Cơ Cấu Tổ Chức</em>; logo hiển thị trong sơ đồ tổ chức và trên thẻ nhân sự của công ty đó.</li></ul><h3 id="🏖️-nghi-phep-1" tabindex="-1">🏖️ Nghỉ phép <a class="header-anchor" href="#🏖️-nghi-phep-1" aria-label="Permalink to &quot;🏖️ Nghỉ phép&quot;">​</a></h3><ul><li><strong>Loại phép áp dụng cho nhiều công ty</strong> — một loại phép có thể gán cho nhiều công ty có chính sách riêng (không chọn = áp dụng tất cả).</li><li><strong>Chính sách phép năm theo công ty</strong> — cộng phép tự động chọn đúng chính sách theo Công ty + Hình thức lao động.</li><li><strong>Quỹ Phép Nhân Sự</strong>: sửa lại cách tính &quot;đã cộng / đã dùng&quot; cho chính xác, lọc theo công ty, thêm thẻ tổng quan và <strong>xuất Excel</strong>.</li></ul><h3 id="🧑‍🤝‍🧑-nguoi-dung" tabindex="-1">🧑‍🤝‍🧑 Người dùng <a class="header-anchor" href="#🧑‍🤝‍🧑-nguoi-dung" aria-label="Permalink to &quot;🧑‍🤝‍🧑 Người dùng&quot;">​</a></h3><ul><li><strong>Logo công ty trên thẻ nhân sự</strong> (chế độ xem Thẻ) ở góc phải mỗi card.</li></ul><h3 id="📘-trung-tam-tro-giup" tabindex="-1">📘 Trung Tâm Trợ Giúp <a class="header-anchor" href="#📘-trung-tam-tro-giup" aria-label="Permalink to &quot;📘 Trung Tâm Trợ Giúp&quot;">​</a></h3><ul><li><strong>Trợ giúp theo ngữ cảnh</strong> — nút <strong>?</strong> trên thanh trên cùng mở đúng trang hướng dẫn của module bạn đang xem.</li><li>Thêm <strong>widget phản hồi</strong> cuối mỗi trang và lối tắt <strong>mở Ticket Hỗ trợ</strong>.</li></ul>',23)])])}const p=t(a,[["render",o]]);export{m as __pageData,p as default};
